@Entity
@Table(name = "reservation")
public class Reservation extends Subject {

    /** English implementation note. */
    public static final int CHECK_IN_TOLERANCE_MINUTES = 10;

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private LocalDate date;


    // English implementation note.
    // English implementation note.
    @Column(name = "status", nullable = false)
    private String stateName;

    @Transient
    private ReservationState status;

    /** English implementation note. */
    @PostLoad
    @PostPersist
    @PostUpdate
    private void initializeState() {
        if ("ACTIVE".equals(stateName)) this.status = ActiveState.getInstance();
        else if ("CANCELLED".equals(stateName)) this.status = CancelledState.getInstance();
        else if ("EXPIRED".equals(stateName)) this.status = ExpiredState.getInstance();
        else if ("CONFIRMED".equals(stateName)) this.status = ConfirmedState.getInstance();
        else if ("COMPLETED".equals(stateName)) this.status = CompletedState.getInstance();
    }

    // English implementation note.
    // English implementation note.
    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "student_id", nullable = false)
    private Student student;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "seat_id", nullable = false)
    private Seat seat;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "time_slot_id", nullable = false)
    private TimeSlot timeSlot;

    // English implementation note.
    @Column(name = "reminder_sent", nullable = false)
    private boolean reminderSent = false;

    public Reservation() { /* Costruttore empty richiesto da JPA. */ }

    // English implementation note.
    public Long getId() { return id; }

    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }

    public ReservationState getState() {
        if (this.status == null && this.stateName != null) initializeState();
        return status;
    }

    /**
      * English implementation note.
     */
    public void setState(ReservationState status) {
        if (status == null) {
            throw new IllegalArgumentException("Reservation status cannot be null");
        }
        this.status = status;
        this.stateName = status.getStatusEnum().name();
        notifyObservers();
    }

    public boolean isReminderSent() {
        return reminderSent;
    }
    public void setReminderSent(boolean reminderSent) {
        this.reminderSent = reminderSent;
    }

    // English implementation note.

    /** English implementation note. */
    public void cancelReservation() {
        validateCancellationWindow();
        boolean cancelled = getState().cancel(this);
        if (!cancelled) {
            throw new IllegalStateException(
                    "The reservation cannot be cancelled in its current status: " + getState().getStatusEnum());
        }
    }

    /** English implementation note. */
    public void performCheckIn() {
        boolean confirmed = getState().checkIn(this);
        if (!confirmed) {
            throw new IllegalStateException(
                    "Check-in is not permitted in the current status: " + getState().getStatusEnum());
        }
    }

    /** English implementation note. */
    public void manageEnd() {
        getState().manageEnd(this);
    }

    /**
      * English implementation note.
      * English implementation note.
      * English implementation note.
     */
    public void forceCancelReservation() {
        this.status = CancelledState.getInstance();
        this.stateName = this.status.getStatusEnum().name();
    }

    /**
      * English implementation note.
      * English implementation note.
      * English implementation note.
      * English implementation note.
     */
    public void validateActiveReservationForCurrentDate() {
        if (getState() == null || getState().getStatusEnum() != StatusEnum.ACTIVE) {
            throw new IllegalStateException("The reservation is not in ACTIVE status");
        }
        if (!LocalDate.now(ZoneId.of("Europe/Rome")).equals(date)) {
            throw new IllegalStateException("Check-in is only permitted on the reservation date");
        }
        LocalDateTime deadline = LocalDateTime.of(date, timeSlot.getStartTime())
                .plusMinutes(CHECK_IN_TOLERANCE_MINUTES);
        if (LocalDateTime.now(ZoneId.of("Europe/Rome")).isAfter(deadline)) {
            throw new IllegalStateException("check-in tolerance of " + CHECK_IN_TOLERANCE_MINUTES
                    + " minutes after the time slot began has been exceeded");
        }
    }

    // English implementation note.
    private void validateCancellationWindow() {
        if (date == null || timeSlot == null) {
            throw new IllegalStateException("Reservation has no date or time slot");
        }
        LocalDateTime start = LocalDateTime.of(date, timeSlot.getStartTime());
        if (LocalDateTime.now(ZoneId.of("Europe/Rome")).isAfter(start.minusHours(6))) {
            throw new IllegalStateException(
                    "Cancellation is not permitted less than 6 hours before the time slot starts");
        }
    }

    public Student getStudent() { return student; }

    public void setStudent(Student student) {
        this.student = student;
    }

    public Seat getSeat() { return seat; }
    public void setSeat(Seat seat) { this.seat = seat; }

    public TimeSlot getTimeSlot() { return timeSlot; }
    public void setTimeSlot(TimeSlot timeSlot) { this.timeSlot = timeSlot; }

    // --- Pattern Observer (Subject) ---
    @Override
    public void notifyObservers() {
        for (Observer obs : observers) {
            obs.update(this);
        }
    }
}
