/**
  * English implementation note.
  * English implementation note.
 * manageEnd in EXPIRED.
 */
public class ActiveState implements ReservationState {

    private static ActiveState instance;

    private ActiveState() {}

    public static ActiveState getInstance() {
        if (instance == null) {
            instance = new ActiveState();
        }
        return instance;
    }

    @Override
    public boolean cancel(Reservation p) {
        p.setState(CancelledState.getInstance());
        return true;
    }

    @Override
    public boolean checkIn(Reservation p) {
        p.setState(ConfirmedState.getInstance());
        return true;
    }

    @Override
    public void manageEnd(Reservation p) {
        p.setState(ExpiredState.getInstance());
    }

